from decimal import Decimal, InvalidOperation
from typing import Any


def _decimal(value: Any) -> Decimal:
    """Convert legacy numeric values, treating missing/empty values as zero."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    try:
        result = Decimal(str(value))
        return result if result.is_finite() else Decimal("0")
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _account_sort_key(account: dict) -> tuple:
    """Provide a deterministic ascending key for typical account primary keys."""
    acct_id = account.get("ACCT_ID", "")

    if isinstance(acct_id, (int, float, Decimal)) and not isinstance(acct_id, bool):
        return (0, _decimal(acct_id))

    if isinstance(acct_id, str):
        return (1, acct_id)

    return (2, type(acct_id).__name__, repr(acct_id))


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """
    Apply the nightly credit-hold sweep without mutating the supplied rows.
    """
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible_indexes = [
        index
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]

    for index in sorted(eligible_indexes, key=lambda i: _account_sort_key(accounts[i])):
        original_account = accounts[index]
        account = new_accounts[index]
        acct_id = original_account.get("ACCT_ID")

        exposure = Decimal("0")
        for order in orders:
            if (
                order.get("ACCT_ID") == acct_id
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _decimal(order.get("TOT_AMT"))

        credit_limit = _decimal(original_account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= credit_limit * Decimal("8") / Decimal("10") and account.get(
            "CRED_HOLD"
        ) == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
